  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 Conquest: Joshua$j$, $j${"readings": [{"title": "Joshua 1 (King James Version)", "url": "/portal/bible/Joshua/1"}, {"title": "Joshua 3 (King James Version)", "url": "/portal/bible/Joshua/3"}, {"title": "Joshua 6 (King James Version)", "url": "/portal/bible/Joshua/6"}, {"title": "Joshua 24 (King James Version)", "url": "/portal/bible/Joshua/24"}], "body": "Read Joshua 1, 3, 6 and 24 in the King James Version. Then read this lesson.\n\nJoshua was Moses' helper and the man God chose to lead Israel across the Jordan River into the promised land. God told him to be strong and courageous and to meditate on the book of the law day and night. Israel crossed the Jordan on dry ground, the walls of Jericho fell after the people marched around the city for seven days, and the tribes came to possess the land one region at a time. The land was then divided among the twelve tribes. At the end of his life Joshua called the nation to choose whom they would serve.\n\nKey words: conquest, inheritance, courage, obedience, choose.\n\nYour task: (1) Name the river Israel crossed to enter the land. (2) Tell how the walls of Jericho fell. (3) Write Joshua 24:15 in your own words and say what choice Joshua made for his house.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Welcome back. Unit 1 gave us the Law. Now we turn to the historical books, and the first of them is Joshua. It picks up the story right where Deuteronomy ends. Moses is dead, the people stand on the east side of the Jordan River, and God speaks to a new leader.\n\nGod told Joshua, Have not I commanded thee? Be strong and of a good courage; be not afraid, neither be thou dismayed: for the LORD thy God is with thee whithersoever thou goest. That is Joshua 1:9. Notice the reason for courage. It is not that Joshua was strong. It is that the LORD was with him.\n\nThe people crossed the Jordan on dry ground, just as their parents had crossed the Red Sea. The priests carried the ark of the covenant into the water, and the river stopped. God was showing the new generation that the same God who delivered their fathers was still with them.\n\nThen came Jericho, a walled city that stood in their way. God gave an unusual battle plan. For six days the army marched around the city once a day, and on the seventh day they marched around seven times, the priests blew the trumpets, the people shouted, and the walls fell flat. The victory came by obedience and trust, not by a siege.\n\nThe rest of the book tells how the tribes took possession of the land and how it was divided among them. Each tribe received an inheritance, a place that God had promised to Abraham centuries before. Joshua 21:45 says, There failed not ought of any good thing which the LORD had spoken unto the house of Israel; all came to pass. God keeps His promises.\n\nNear the end of his life Joshua gathered the nation and gave them a choice. Joshua 24:15 says, choose you this day whom ye will serve; but as for me and my house, we will serve the LORD. Every person and every family has to answer that question.\n\nYour task is to name the river, tell how Jericho fell, and put Joshua 24:15 in your own words. Then take the four question check.\n\nCourage comes from knowing God is with you. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 Conquest: Joshua$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 Judges and Ruth$j$, $j${"readings": [{"title": "Judges 2 (King James Version)", "url": "/portal/bible/Judges/2"}, {"title": "Judges 6 (King James Version)", "url": "/portal/bible/Judges/6"}, {"title": "Judges 21 (King James Version)", "url": "/portal/bible/Judges/21"}, {"title": "Ruth 1 (King James Version)", "url": "/portal/bible/Ruth/1"}], "body": "Read Judges 2, Judges 6, Judges 21:25 and Ruth 1 in the King James Version. Then read this lesson.\n\nAfter Joshua's generation died, Israel forgot the LORD. The book of Judges records a repeating cycle: the people sinned, God allowed an enemy to oppress them, the people cried out, and God raised up a judge to deliver them. A judge was a leader chosen by God to rescue the nation. Deborah, Gideon and Samson are among the best known. The book closes with a sad summary: there was no king in Israel, and every man did what was right in his own eyes.\n\nRuth is a short book from the same period. A woman from Moab named Ruth stayed loyal to her mother in law Naomi, came to Bethlehem, and married Boaz, a kind relative who redeemed the family land. Ruth became the great grandmother of King David.\n\nKey words: judge, cycle, deliverance, loyalty, redeemer.\n\nYour task: (1) List the four steps of the cycle in Judges. (2) Name two judges. (3) Explain why Ruth matters in the family line of David.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Joshua ends with a strong nation. Judges begins with a weak one. Judges 2 says that another generation arose after them, which knew not the LORD, nor yet the works which he had done for Israel. One generation of forgetting was all it took.\n\nThe book of Judges shows a cycle that repeats again and again. First, Israel sins and serves the gods of the nations around them. Second, God allows an enemy to oppress them. Third, the people cry out to the LORD. Fourth, God raises up a judge to deliver them. Then the land has rest, and the cycle begins over.\n\nA judge was not a courtroom judge. A judge was a deliverer, a leader chosen by God to rescue His people. Deborah was a prophetess who led Israel to victory over a Canaanite army. Gideon was a farmer who felt small, yet God used three hundred men with trumpets and torches to defeat a huge army. Samson was given great strength, but his story reminds us that gifts can be wasted without self control.\n\nThe book closes with a sentence that explains everything. Judges 21:25 says, In those days there was no king in Israel: every man did that which was right in his own eyes. When people do whatever they think is right, without God as their standard, the result is confusion and harm.\n\nRight after that dark book we find a bright one. Ruth is a short love and loyalty story from the same time. Naomi lost her husband and her sons in the land of Moab. Her daughter in law Ruth, a Moabite, refused to leave her. Ruth said, Intreat me not to leave thee, or to return from following after thee: for whither thou goest, I will go; and where thou lodgest, I will lodge: thy people shall be my people, and thy God my God.\n\nRuth came to Bethlehem and gleaned grain in the field of Boaz, a relative of Naomi's family. Boaz acted as a kinsman redeemer. He bought back the family land and married Ruth. Their great grandson was David, Israel's greatest king. A foreign woman who chose the God of Israel became part of the line that leads to the Messiah.\n\nYour task is to list the four steps of the cycle, name two judges, and explain why Ruth matters. Then take the four question check.\n\nEven in dark times God is working out His plan. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 Judges and Ruth$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 The Kingdom: Samuel, Saul, David and Solomon$j$, $j${"readings": [{"title": "1 Samuel 3 (King James Version)", "url": "/portal/bible/1Samuel/3"}, {"title": "1 Samuel 16 (King James Version)", "url": "/portal/bible/1Samuel/16"}, {"title": "2 Samuel 7 (King James Version)", "url": "/portal/bible/2Samuel/7"}, {"title": "1 Kings 3 (King James Version)", "url": "/portal/bible/1Kings/3"}], "body": "Read 1 Samuel 3 and 16, 2 Samuel 7 and 1 Kings 3 in the King James Version. Then read this lesson.\n\nFirst and Second Samuel tell how Israel moved from judges to kings. Samuel was a prophet and the last of the judges. The people asked for a king like the nations around them, and God gave them Saul, who began well but disobeyed. God then sent Samuel to anoint David, a shepherd boy, who defeated Goliath and later became king. God made a covenant with David in 2 Samuel 7, promising that his house and throne would last forever. David's son Solomon built the temple in Jerusalem and was known for his wisdom.\n\nKey words: prophet, king, anointed, covenant with David, temple.\n\nYour task: (1) Name Israel's first king and the king who followed him. (2) Say what God told Samuel about how He sees people (1 Samuel 16:7). (3) Explain the promise God made to David in 2 Samuel 7:16.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "The books of Samuel mark a turning point. Israel had been ruled by judges. Now the people wanted a king. This section of the Old Testament includes some of the best known stories in the Bible, and it also reaches one of the most important promises.\n\nSamuel was born to a woman named Hannah, who prayed for a child and gave him back to the LORD. As a boy, Samuel heard God call his name in the night. He grew up to be a prophet and the last of the judges. When he was old, the people asked, make us a king to judge us like all the nations. God told Samuel to give them what they asked, though it showed they had not fully trusted Him as their King.\n\nSaul was the first king. He was tall and impressive, but he disobeyed God more than once, and God rejected him as king. So God sent Samuel to the house of Jesse in Bethlehem. Samuel looked at the older sons and thought one of them must be the one. But God said in 1 Samuel 16:7, for the LORD seeth not as man seeth; for man looketh on the outward appearance, but the LORD looketh on the heart. The chosen one was David, the youngest, who was out keeping the sheep.\n\nDavid defeated the giant Goliath with a sling and a stone, because he trusted in the name of the LORD. Years later he became king over all Israel and made Jerusalem his capital. David was not perfect. He sinned seriously, and 2 Samuel records his repentance. Yet God called him a man after His own heart.\n\nThe high point of the story is 2 Samuel 7. David wanted to build God a house. God answered that He would build David a house instead. God said, And thine house and thy kingdom shall be established for ever before thee: thy throne shall be established for ever. This is called the covenant with David. It points far ahead to a King from David's line who would reign forever.\n\nDavid's son Solomon followed him. When God offered to give him anything, Solomon asked for an understanding heart to judge God's people. God gave him wisdom, riches and honor, and Solomon built the temple in Jerusalem. The kingdom was at its height.\n\nYour task is to name the first two kings, tell what God told Samuel about how He sees people, and explain the promise to David. Then take the four question check.\n\nMan looks at the outside, but God looks at the heart. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 The Kingdom: Samuel, Saul, David and Solomon$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 Division, Exile and Return: Kings, Chronicles, Ezra, Nehemiah and Esther$j$, $j${"readings": [{"title": "1 Kings 12 (King James Version)", "url": "/portal/bible/1Kings/12"}, {"title": "2 Chronicles 7 (King James Version)", "url": "/portal/bible/2Chronicles/7"}, {"title": "Nehemiah 8 (King James Version)", "url": "/portal/bible/Nehemiah/8"}, {"title": "Esther 4 (King James Version)", "url": "/portal/bible/Esther/4"}], "body": "Read 1 Kings 12, 2 Chronicles 7, Nehemiah 8 and Esther 4 in the King James Version. Then read this lesson.\n\nAfter Solomon died, the kingdom split. The ten northern tribes kept the name Israel and the two southern tribes became Judah, ruled by David's descendants. The northern kingdom fell to Assyria. The southern kingdom lasted longer but was taken to Babylon in exile because of its sin. First and Second Kings and First and Second Chronicles tell this history from two angles. After seventy years God stirred a king of Persia to let the people return. Ezra led a spiritual return and Nehemiah rebuilt the walls of Jerusalem. The book of Esther tells how God protected the Jewish people who stayed in Persia.\n\nKey words: divided kingdom, exile, remnant, return, providence.\n\nYour task: (1) Name the two kingdoms after the split. (2) Say who led the nation into exile and who carried them back. (3) Explain what Mordecai meant by the words for such a time as this.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Solomon's reign was glorious, but his heart drifted from the LORD, and after his death the kingdom divided. This is the story told in First and Second Kings and again, from a different angle, in First and Second Chronicles.\n\nThe ten northern tribes broke away under a king named Jeroboam. They kept the name Israel. The two southern tribes, Judah and Benjamin, stayed with David's family, and that kingdom was called Judah. Jeroboam set up golden calves so that his people would not go to the temple in Jerusalem, and almost every king after him in the north did evil. About two hundred years later, in the days of Hoshea, the northern kingdom fell to the empire of Assyria and its people were scattered.\n\nJudah had some good kings, such as Hezekiah and Josiah, who called the people back to God. But the nation as a whole kept turning away. The prophets warned them again and again. Finally Babylon, led by King Nebuchadnezzar, took Jerusalem, burned the temple and carried the people into exile.\n\nIn the Chronicles God gave a promise for just such a time. 2 Chronicles 7:14 says, If my people, which are called by my name, shall humble themselves, and pray, and seek my face, and turn from their wicked ways; then will I hear from heaven, and will forgive their sin, and will heal their land. The way back is always humility, prayer and repentance.\n\nAfter seventy years, God stirred up Cyrus, the king of Persia, to let the Jews go home. Ezra, a priest and scribe, led a group back and taught the people the law. Nehemiah, a cupbearer to the king, led the rebuilding of the walls of Jerusalem in only fifty two days. When Ezra read the law aloud, the people wept, and Nehemiah told them in Nehemiah 8:10, the joy of the LORD is your strength.\n\nThe last historical book is Esther. Many Jews still lived in Persia. A wicked man named Haman plotted to destroy them. Esther, a Jewish woman who had become queen, was asked by her cousin Mordecai to speak to the king. Mordecai said in Esther 4:14, who knoweth whether thou art come to the kingdom for such a time as this? Esther risked her life, and God saved His people. The name of God is not written in the book of Esther, but His hand is on every page.\n\nYour task is to name the two kingdoms, say who carried the people into exile and who led them back, and explain what Mordecai meant. Then take the four question check and the Unit 2 quiz.\n\nGod places each of us for such a time as this. Excellence, Faith, Purpose. I will see you in the next unit."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 Division, Exile and Return: Kings, Chronicles, Ezra, Nehemiah and Esther$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: Lessons from the Leaders$j$, $j${"prompt": "Choose one leader from this unit: Joshua, Deborah or Gideon, Ruth, David, Nehemiah or Esther. Write one paragraph of 150 to 200 words. Tell what the person did, explain what faith or courage the person showed, and say what a student your age can learn from the example. Quote at least one verse from the King James Version.", "rubric": "Total 100. Accurate account of what the leader did: 30. Explains the faith or courage shown: 20. Applies the lesson to student life, with a quoted King James Version verse: 30. Clear writing and correct conventions: 20."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: Lessons from the Leaders$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: Choosing Whom We Will Serve$j$, $j${"prompt": "Joshua told Israel to choose whom they would serve. Think about a choice you face as a student where you have to decide what you will stand for. Describe the choice and explain how knowing the stories in this unit could help you decide. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: Choosing Whom We Will Serve$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: Conquest: Joshua$j$, $j${"questions": [{"q": "Who became Israel's leader after Moses died?", "options": ["Caleb", "Samuel", "Joshua", "Aaron"]}, {"q": "Which river did Israel cross to enter the promised land?", "options": ["The Euphrates", "The Jordan", "The Nile", "The Red Sea"]}, {"q": "How did the walls of Jericho fall?", "options": ["The army dug under them", "A storm destroyed them", "Soldiers climbed them with ladders", "Israel marched, the priests blew trumpets and the people shouted"]}, {"q": "What choice did Joshua announce in Joshua 24:15?", "options": ["He would become king", "He and his house would serve the LORD", "He would build a palace", "He would go back to Egypt"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Conquest: Joshua$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,3,1}'::int[], array[$j$God chose Joshua to lead Israel into the promised land (Joshua 1:1 and 2).$j$,$j$Israel crossed the Jordan River on dry ground (Joshua 3).$j$,$j$The walls fell after Israel marched around the city and shouted at God's command (Joshua 6).$j$,$j$Joshua said, as for me and my house, we will serve the LORD.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Conquest: Joshua$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Judges and Ruth$j$, $j${"questions": [{"q": "Which choice lists the cycle in the book of Judges in order?", "options": ["Judge, sin, rest, enemy", "Rest, judge, enemy, sin", "Sin, oppression, a cry for help, a judge delivers", "Enemy, rest, sin, judge"]}, {"q": "What was a judge in the book of Judges?", "options": ["A courtroom official", "A leader God raised up to deliver Israel", "A foreign king", "A priest at the tabernacle"]}, {"q": "What does Judges 21:25 say about the time of the judges?", "options": ["Israel lived in Egypt", "Israel had no enemies", "Israel had a good king", "There was no king and every man did what was right in his own eyes"]}, {"q": "Who was Ruth, and why does she matter?", "options": ["A Moabite woman who became the great grandmother of King David", "The wife of Samson", "A prophetess who led Israel in war", "A judge who defeated Midian"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Judges and Ruth$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,3,0}'::int[], array[$j$Israel sinned, God allowed oppression, the people cried out, and God raised up a judge.$j$,$j$A judge was a God chosen deliverer of Israel.$j$,$j$The book ends by describing a nation without a king and without a standard.$j$,$j$Ruth stayed loyal to Naomi, married Boaz, and became the great grandmother of David (Ruth 4).$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Judges and Ruth$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: The Kingdom: Samuel, Saul, David and Solomon$j$, $j${"questions": [{"q": "Who was the first king of Israel?", "options": ["Solomon", "David", "Samuel", "Saul"]}, {"q": "According to 1 Samuel 16:7, what does the LORD look at?", "options": ["The heart", "A person's age", "A person's wealth", "The outward appearance"]}, {"q": "What did God promise David in 2 Samuel 7?", "options": ["That he would build the ark", "That he would live in Egypt", "That he would never face an enemy", "That his throne would be established for ever"]}, {"q": "What did Solomon build in Jerusalem?", "options": ["The temple", "The ark", "The tabernacle", "The walls of Jericho"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: The Kingdom: Samuel, Saul, David and Solomon$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,3,0}'::int[], array[$j$Saul was anointed as Israel's first king (1 Samuel 10).$j$,$j$The LORD looketh on the heart, not on the outward appearance.$j$,$j$God promised that David's house, kingdom and throne would be established for ever.$j$,$j$Solomon built the temple of the LORD in Jerusalem (1 Kings 6).$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: The Kingdom: Samuel, Saul, David and Solomon$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: Division, Exile and Return: Kings, Chronicles, Ezra, Nehemiah and Esther$j$, $j${"questions": [{"q": "What were the two kingdoms called after Solomon's death?", "options": ["Israel in the north and Judah in the south", "Egypt and Assyria", "Moab and Edom", "Jerusalem and Samaria"]}, {"q": "Which empire took the people of Judah into exile and burned the temple?", "options": ["Babylon", "Rome", "Greece", "Egypt"]}, {"q": "Who led the rebuilding of the walls of Jerusalem?", "options": ["Mordecai", "Nehemiah", "Ezra", "Esther"]}, {"q": "What did Mordecai suggest about Esther when he said, for such a time as this?", "options": ["She should leave Persia", "God may have placed her as queen to save her people", "She should hide her identity forever", "She should ignore Haman"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Division, Exile and Return: Kings, Chronicles, Ezra, Nehemiah and Esther$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,1,1}'::int[], array[$j$The ten northern tribes were Israel, and the southern kingdom was Judah.$j$,$j$Babylon under Nebuchadnezzar took Judah into exile.$j$,$j$Nehemiah led the rebuilding of the walls.$j$,$j$Mordecai saw that God had put Esther in a place of influence for a reason.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Division, Exile and Return: Kings, Chronicles, Ezra, Nehemiah and Esther$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: The Historical Books, Joshua to Esther$j$, $j${"questions": [{"q": "What did the LORD tell Joshua in Joshua 1:9?", "options": ["Fight alone", "Build a temple", "Be strong and of a good courage, for the LORD is with you", "Return to Egypt"]}, {"q": "What repeated pattern fills the book of Judges?", "options": ["War, treaty, trade, peace", "Teaching, exile, return, rest", "Peace, harvest, feast, rest", "Sin, oppression, a cry for help, deliverance"]}, {"q": "Which woman said, whither thou goest, I will go?", "options": ["Deborah", "Ruth", "Esther", "Hannah"]}, {"q": "Who was anointed king after God rejected Saul?", "options": ["David", "Samuel", "Jonathan", "Solomon"]}, {"q": "What happened to the northern kingdom of Israel?", "options": ["It was conquered by Assyria and scattered", "It was never attacked", "It joined Egypt", "It was taken to Persia"]}, {"q": "Which book shows God protecting the Jewish people in Persia?", "options": ["Ruth", "Nehemiah", "Esther", "Ezra"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: The Historical Books, Joshua to Esther$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,1,0,0,2}'::int[], array[$j$God told Joshua to be strong and of a good courage because the LORD was with him.$j$,$j$Israel sinned, suffered, cried out, and was delivered by a judge.$j$,$j$Ruth said these words to Naomi in Ruth 1:16.$j$,$j$Samuel anointed David, the youngest son of Jesse, in 1 Samuel 16.$j$,$j$Assyria conquered the northern kingdom and scattered its people.$j$,$j$Esther risked her life and God saved His people from Haman's plot.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: The Historical Books, Joshua to Esther$j$ on conflict (item_id) do nothing;
